/// Runtime support for the code generated by `strict: true`.
public enum StrictDecoding {
    private struct AnyKey: CodingKey {
        let stringValue: String
        let intValue: Int? = nil

        init?(stringValue: String) {
            self.stringValue = stringValue
        }

        init?(intValue _: Int) {
            nil
        }
    }

    /// Throws `DecodingError.dataCorrupted` when the decoder's object has a key outside `allowed`.
    public static func rejectUnknownKeys(in decoder: Decoder, allowed: [any CodingKey]) throws {
        let known = Set(allowed.map(\.stringValue))
        let container = try decoder.container(keyedBy: AnyKey.self)
        guard let unknown = container.allKeys.map(\.stringValue).filter({ !known.contains($0) }).sorted().first else {
            return
        }
        throw DecodingError.dataCorrupted(
            .init(codingPath: decoder.codingPath, debugDescription: "Unknown key \(unknown)")
        )
    }
}
